def _structural_tp_target(
    zc: ZoneContext,
    entry: float,
    atr: float,
    side_u: str,
    level_index: int,
) -> float:
    """TP по индексу: 0=ближайшая зона, 1=дальняя (tp2), 2+=tp2 + extra ATR."""
    idx = max(0, int(level_index or 0))
    if side_u == "BUY":
        tp1, tp2 = zc.structural_tp_long(entry, atr)
        if idx <= 0:
            return tp1
        extra = max(0, idx - 1) * atr * 1.5
        return tp2 + extra
    tp1, tp2 = zc.structural_tp_short(entry, atr)
    if idx <= 0:
        return tp1
    extra = max(0, idx - 1) * atr * 1.5
    return tp2 - extra

