"""
Мягкие правила входа (Entry Soft Score) — некатегоричные факторы с базовыми баллами.
Веса правил усиливаются через rule_weight_tracker после 2 недель подтверждённой точности.
"""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Dict, List, Mapping, Optional

SOFT_SCORE_BASE = 50.0

# id → базовые баллы (отрицательные — штрафы, их вес не усиливаем)
RULE_POINTS: Dict[str, float] = {
    "hour_green": 15.0,
    "hour_red": -12.0,
    "htf_aligned": 18.0,
    "htf_misaligned": -20.0,
    "regime_trend": 15.0,
    "regime_chop": -8.0,
    "adx_ok": 12.0,
    "adx_strong": 8.0,
    "adx_weak": -15.0,
    "atr_sweet": 10.0,
    "atr_extreme": 5.0,
    "imb_strong": 10.0,
    "volume_2x": 5.0,
    "short_green_hour": 5.0,
    "spread_wide": -5.0,
}

POSITIVE_RULE_IDS = frozenset(rid for rid, pts in RULE_POINTS.items() if pts > 0)


@dataclass
class SoftScoreResult:
    score: float
    label: str
    active_rules: List[str] = field(default_factory=list)
    breakdown: Dict[str, float] = field(default_factory=dict)
    size_mult: float = 1.0
    confidence_boost: float = 0.0


def _f(ctx: Mapping[str, Any], key: str, default: float = 0.0) -> float:
    try:
        return float(ctx.get(key, default) or default)
    except (TypeError, ValueError):
        return default


def _s(ctx: Mapping[str, Any], key: str) -> str:
    return str(ctx.get(key, "") or "").strip().lower()


def _local_hour(ctx: Mapping[str, Any], tz_offset: int = 3) -> int:
    if "local_hour" in ctx:
        try:
            return int(ctx["local_hour"]) % 24
        except (TypeError, ValueError):
            pass
    return 0


def _is_buy(side: str) -> bool:
    return str(side or "").strip().upper() in ("BUY", "LONG")


def detect_active_rules(
    entry_context: Optional[Mapping[str, Any]],
    *,
    side: str = "",
    tz_offset: int = 3,
) -> List[str]:
    """Какие правила сработали на входе (по entry_context)."""
    if not entry_context:
        return []
    ctx = entry_context
    side_u = str(side or ctx.get("side") or "").upper()
    hour = _local_hour(ctx, tz_offset)
    active: List[str] = []

    if hour in (11, 17, 18, 19):
        active.append("hour_green")
    if hour in (1, 3, 14, 15, 16, 23):
        active.append("hour_red")

    htf = _s(ctx, "htf_trend")
    if _is_buy(side_u) and htf == "bullish":
        active.append("htf_aligned")
    elif (not _is_buy(side_u)) and side_u in ("SELL", "SHORT") and htf == "bearish":
        active.append("htf_aligned")
    elif htf in ("bullish", "bearish") and side_u:
        if (_is_buy(side_u) and htf == "bearish") or (
            (not _is_buy(side_u)) and htf == "bullish"
        ):
            active.append("htf_misaligned")

    regime = _s(ctx, "regime")
    if regime == "trend":
        active.append("regime_trend")
    elif regime == "chop":
        active.append("regime_chop")

    adx = _f(ctx, "adx")
    if adx >= 25:
        active.append("adx_ok")
        active.append("adx_strong")
    elif adx >= 15:
        active.append("adx_ok")
    elif adx > 0 and adx < 15:
        active.append("adx_weak")

    atr = _f(ctx, "atr_pct")
    if 0.15 <= atr < 1.5:
        active.append("atr_sweet")
    elif atr >= 1.5:
        active.append("atr_extreme")

    imb = abs(_f(ctx, "normalized_imbalance"))
    if 0.25 <= imb < 0.55:
        active.append("imb_strong")

    vol = _f(ctx, "volume_24h_usdt")
    if vol >= 20_000_000:
        active.append("volume_2x")

    if (not _is_buy(side_u)) and side_u in ("SELL", "SHORT") and "hour_green" in active:
        active.append("short_green_hour")

    spread = _f(ctx, "spread_pct")
    if spread >= 0.008:
        active.append("spread_wide")

    return active


def _label_for_score(score: float, cfg: Dict[str, Any]) -> str:
    block = cfg.get("rule_weight_learning", {})
    if not isinstance(block, dict):
        block = {}
    fav = float(block.get("favorable_threshold", 65) or 65)
    neu = float(block.get("neutral_threshold", 50) or 50)
    caution = float(block.get("caution_threshold", 40) or 40)
    if score >= fav:
        return "favorable"
    if score >= neu:
        return "neutral"
    if score >= caution:
        return "caution"
    return "weak"


def compute_soft_score(
    entry_context: Optional[Mapping[str, Any]],
    *,
    side: str = "",
    cfg: Optional[Dict[str, Any]] = None,
    rule_weights: Optional[Mapping[str, float]] = None,
) -> SoftScoreResult:
    """
    Entry Soft Score с учётом обученных весов (мультипликаторы ≥ 1 только для + правил).
    """
    cfg = cfg or {}
    rwl = cfg.get("rule_weight_learning", {})
    if not isinstance(rwl, dict):
        rwl = {}
    tz = int(cfg.get("timezone_offset", 3) or 3)
    weights = dict(rule_weights or {})
    max_conf_boost = float(rwl.get("max_confidence_boost", 0.05) or 0.05)
    max_size_mult = float(rwl.get("max_size_mult", 1.12) or 1.12)

    active = detect_active_rules(entry_context, side=side, tz_offset=tz)
    breakdown: Dict[str, float] = {}
    total = SOFT_SCORE_BASE
    validated_hits = 0

    for rid in active:
        base = RULE_POINTS.get(rid, 0.0)
        if base == 0.0:
            continue
        mult = 1.0
        if base > 0 and rid in POSITIVE_RULE_IDS:
            mult = float(weights.get(rid, 1.0) or 1.0)
            if mult > 1.001:
                validated_hits += 1
        pts = base * mult
        breakdown[rid] = round(pts, 3)
        total += pts

    score = round(total, 2)
    label = _label_for_score(score, cfg)

    # Небольшой boost размера/confidence за validated правила (не bypass gate)
    boost_factor = min(1.0, validated_hits * 0.25)
    size_mult = 1.0 + min(max_size_mult - 1.0, boost_factor * (max_size_mult - 1.0))
    confidence_boost = min(max_conf_boost, validated_hits * 0.015)

    return SoftScoreResult(
        score=score,
        label=label,
        active_rules=active,
        breakdown=breakdown,
        size_mult=round(size_mult, 4),
        confidence_boost=round(confidence_boost, 4),
    )

"""
Обучение весов правил входа: если правило 2 недели подряд «работает» — усилить его вес.
"""
from __future__ import annotations

import json
import logging
import time
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any, Dict, List, Mapping, Optional

from prd_agent.entry.entry_soft_rules import POSITIVE_RULE_IDS, detect_active_rules
from prd_agent.evolution.feedback_dataset import load_journal_pairs

logger = logging.getLogger("prd_agent.rule_weights")


class RuleWeightTracker:
    """Статистика правил по закрытым сделкам → мультипликаторы весов."""

    def __init__(self, data_dir: Path, cfg: Mapping[str, Any]):
        self.data_dir = Path(data_dir)
        self.cfg = dict(cfg)
        block = cfg.get("rule_weight_learning", {})
        self.block = block if isinstance(block, dict) else {}
        self.enabled = bool(self.block.get("enabled", True))
        self.lookback_days = max(1.0, float(self.block.get("lookback_days", 14) or 14))
        self.min_samples = max(1, int(self.block.get("min_samples", 5) or 5))
        self.min_win_rate = float(self.block.get("min_win_rate", 0.52) or 0.52)
        self.min_total_pnl = float(self.block.get("min_total_pnl", 0.0) or 0.0)
        self.max_weight_mult = float(self.block.get("max_weight_mult", 1.35) or 1.35)
        self.refresh_interval_sec = max(
            60.0, float(self.block.get("refresh_interval_sec", 3600) or 3600)
        )
        self.tz_offset = int(cfg.get("timezone_offset", 3) or 3)

        learn_dir = self.data_dir / "learning"
        learn_dir.mkdir(parents=True, exist_ok=True)
        self.state_path = learn_dir / "rule_weights_state.json"
        self._last_refresh_ts = 0.0
        self._weights: Dict[str, float] = {}
        self._stats: Dict[str, Dict[str, Any]] = {}
        self._validated: List[str] = []
        self._load_state()

    def _load_state(self) -> None:
        if not self.state_path.is_file():
            return
        try:
            data = json.loads(self.state_path.read_text(encoding="utf-8"))
            self._weights = {
                str(k): float(v) for k, v in (data.get("weights") or {}).items()
            }
            self._stats = dict(data.get("stats") or {})
            self._validated = list(data.get("validated_rules") or [])
            self._last_refresh_ts = float(data.get("last_refresh_ts") or 0)
        except Exception as exc:
            logger.warning("rule_weights load failed: %s", exc)

    def _save_state(self) -> None:
        payload = {
            "updated_at": datetime.now(timezone.utc).isoformat(),
            "lookback_days": self.lookback_days,
            "last_refresh_ts": self._last_refresh_ts,
            "validated_rules": self._validated,
            "weights": self._weights,
            "stats": self._stats,
        }
        try:
            self.state_path.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8"
            )
        except Exception as exc:
            logger.warning("rule_weights save failed: %s", exc)

    @staticmethod
    def _parse_ts(row: Mapping[str, Any]) -> Optional[datetime]:
        for key in ("ts", "time", "closed_at"):
            val = row.get(key)
            if not val:
                continue
            try:
                dt = datetime.fromisoformat(str(val).replace("Z", "+00:00"))
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=timezone.utc)
                return dt.astimezone(timezone.utc)
            except (TypeError, ValueError):
                continue
        return None

    def refresh_from_journal(self, journal_path: Path, *, force: bool = False) -> None:
        if not self.enabled:
            return
        now = time.time()
        if not force and self._last_refresh_ts and now - self._last_refresh_ts < self.refresh_interval_sec:
            return
        if not journal_path.is_file():
            return

        cutoff = datetime.now(timezone.utc) - timedelta(days=self.lookback_days)
        pairs = load_journal_pairs(journal_path)
        stats: Dict[str, Dict[str, Any]] = {
            rid: {"n": 0, "wins": 0, "pnl": 0.0} for rid in POSITIVE_RULE_IDS
        }

        for pair in pairs:
            closed = pair.get("closed") or {}
            entered = pair.get("entered") or {}
            ts = self._parse_ts(closed) or self._parse_ts(entered)
            if ts and ts < cutoff:
                continue
            pnl = float(closed.get("pnl") or pair.get("pnl_usdt") or 0)
            ctx = closed.get("entry_context") or entered.get("entry_context") or {}
            if not isinstance(ctx, dict):
                ctx = {}
            side = str(closed.get("side") or entered.get("side") or "")
            rules = detect_active_rules(ctx, side=side, tz_offset=self.tz_offset)
            for rid in rules:
                if rid not in POSITIVE_RULE_IDS:
                    continue
                bucket = stats.setdefault(rid, {"n": 0, "wins": 0, "pnl": 0.0})
                bucket["n"] += 1
                bucket["pnl"] += pnl
                if pnl > 0:
                    bucket["wins"] += 1

        weights: Dict[str, float] = {}
        validated: List[str] = []
        for rid, bucket in stats.items():
            n = int(bucket.get("n") or 0)
            wins = int(bucket.get("wins") or 0)
            pnl_sum = float(bucket.get("pnl") or 0)
            mult = 1.0
            if n >= self.min_samples:
                wr = wins / n if n else 0.0
                if wr >= self.min_win_rate and pnl_sum > self.min_total_pnl:
                    edge = max(0.0, wr - 0.5)
                    boost = min(self.max_weight_mult - 1.0, 0.08 + edge * 0.6)
                    mult = round(1.0 + boost, 4)
                    validated.append(rid)
            weights[rid] = mult

        self._stats = stats
        self._weights = weights
        self._validated = sorted(validated)
        self._last_refresh_ts = now
        self._save_state()
        if validated:
            logger.info(
                "Rule weights refreshed: validated=%s (lookback=%.0fd, pairs=%d)",
                ",".join(validated),
                self.lookback_days,
                len(pairs),
            )

    def refresh_if_due(self, journal_path: Path, *, force: bool = False) -> None:
        try:
            self.refresh_from_journal(journal_path, force=force)
        except Exception as exc:
            logger.warning("rule_weights refresh: %s", exc)

    def get_weights(self) -> Dict[str, float]:
        return dict(self._weights)

    def get_validated_rules(self) -> List[str]:
        return list(self._validated)

    def summary(self) -> Dict[str, Any]:
        return {
            "enabled": self.enabled,
            "lookback_days": self.lookback_days,
            "validated_rules": self._validated,
            "weights": self._weights,
            "stats": self._stats,
        }

