def _token_path() -> Path:
    base = Path(__file__).resolve().parents[2]
    return base / "data" / "youtube_token.json"


def _secrets_path() -> Path:
    raw = os.getenv("YOUTUBE_CLIENT_SECRETS", "")
    return Path(raw) if raw else Path(__file__).resolve().parents[2] / "secrets" / "youtube_client_secrets.json"


def _get_youtube_service():
    creds = None
    token_file = _token_path()
    if token_file.exists():
        creds = Credentials.from_authorized_user_file(str(token_file), SCOPES)
    if not creds or not creds.valid:
        if creds and creds.expired and creds.refresh_token:
            creds.refresh(Request())
        else:
            secrets = _secrets_path()
            if not secrets.exists():
                raise FileNotFoundError(
                    f"Нет {secrets}. Скачайте OAuth client JSON из Google Cloud Console."
                )
            flow = InstalledAppFlow.from_client_secrets_file(str(secrets), SCOPES)
            creds = flow.run_local_server(port=0)
        token_file.parent.mkdir(parents=True, exist_ok=True)
        token_file.write_text(creds.to_json(), encoding="utf-8")
    return build("youtube", "v3", credentials=creds)


