def _parse_paragraphs(text: str) -> list[str]:
    lines = [ln.strip() for ln in text.strip().splitlines() if ln.strip()]
    paragraphs: list[str] = []
    buf: list[str] = []
    for ln in lines:
        cleaned = re.sub(r"^\d+[\).\s]+", "", ln).strip()
        if re.match(r"^#{1,3}\s", cleaned):
            if buf:
                paragraphs.append(" ".join(buf))
                buf = []
            continue
        buf.append(cleaned)
    if buf:
        paragraphs.append(" ".join(buf))
    return [p for p in paragraphs if len(p) > 20]


def _system_prompt(style: str) -> str:
    return STYLE_PROMPTS.get(style, STYLE_PROMPTS["mixed"])


def generate_script(
    topic: DailyTopic,
    language: str,
    target_minutes: float,
    max_words: int,
    style: str = "funny_curiosities",
) -> VideoScript:
    model = os.environ.get("OPENROUTER_MODEL", "google/gemini-2.5-flash")
    period = PERIOD_LABELS.get(topic.period, topic.period)
    category = CATEGORY_LABELS.get(topic.category, topic.category)
    funny = style == "funny_curiosities"

    if language == "ru":
        subject = topic.title_ru
        if funny:
            user = f"""Напиши СМЕШНОЙ сценарий озвучки на РУССКОМ — исторический курьёз / «анекдот из прошлого».
Тема: {topic.seed}
Период: {period}, тип: {category}
Длина: ~{target_minutes} мин (~{max_words} слов макс.).
Формат: 8–12 абзацев, 2–3 коротких предложения в абзаце.
Подача: юмор, неожиданные повороты, лёгкая ирония. Как рассказ байки другу.
Если история легендарная — одной фразой предупреди. Без жестоких шуток над жертвами."""
        else:
            user = f"""Напиши сценарий озвучки на РУССКОМ.
Тема: {subject}, период: {period}, категория: {category}
~{target_minutes} мин, ~{max_words} слов. 8–14 абзацев."""
        desc_lang = "ru"
    else:
        subject = topic.title_en
        if funny:
            user = f"""Write a FUNNY voice-over script in ENGLISH — historical curiosity / anecdote style.
Topic: {topic.seed}
Period: {topic.period}, type: {category}
Length: ~{target_minutes} min (~{max_words} words max).
Format: 8–12 paragraphs, 2–3 short sentences each.
Tone: witty, punchy, anecdote pacing. If legend/disputed — note briefly."""
        else:
            user = f"""Write a voice-over script in ENGLISH.
Topic: {subject}, ~{target_minutes} min, ~{max_words} words."""
        desc_lang = "en"

    client = _client()
    temperature = 0.88 if funny else 0.75
    resp = client.chat.completions.create(
        model=model,
        messages=[
            {"role": "system", "content": _system_prompt(style)},
            {"role": "user", "content": user},
        ],
        temperature=temperature,
        max_tokens=4096,
    )
    raw = (resp.choices[0].message.content or "").strip()
    paragraphs = _parse_paragraphs(raw)
    if not paragraphs:
        raise RuntimeError(f"LLM вернул пустой сценарий ({language})")

    tags = _default_tags(topic, language, funny)
    description = _make_description(subject, paragraphs, desc_lang, funny)
    return VideoScript(
        language=language,
        subject=subject,
        paragraphs=paragraphs,
        description=description,
        tags=tags,
    )


def _default_tags(topic: DailyTopic, language: str, funny: bool) -> list[str]:
    if funny:
        base = ["history", "funny", "curiosities", topic.period, topic.category]
        if language == "ru":
            base.extend(["история", "юмор", "курьёзы", "анекдот"])
        else:
            base.extend(["historyhumor", "weirdhistory"])
    else:
        base = ["history", "documentary", topic.period, topic.category]
        if language == "ru":
            base.extend(["история", "документальное"])
    return list(dict.fromkeys(base))[:15]


def _make_description(subject: str, paragraphs: list[str], lang: str, funny: bool) -> str:
    hook = paragraphs[0][:200]
    if lang == "ru":
        tags = "#история #юмор #курьёзы #анекдот" if funny else "#история #документальное"
        return f"{subject}\n\n{hook}...\n\n{tags}"
    tags = "#history #funny #weirdhistory" if funny else "#history #documentary"
    return f"{subject}\n\n{hook}...\n\n{tags}"

