def generate_video_terms(
    subject: str,
    script_text: str,
    *,
    match_script_order: bool = True,
    amount: int = 8,
) -> list[str]:
    """
    Возвращает список английских поисковых фраз для Pexels.
    MPT требует English terms — не переводим на русский.
    """
    model = os.environ.get("OPENROUTER_MODEL", "google/gemini-2.5-flash")
    script_excerpt = script_text.strip()
    if len(script_excerpt) > 3500:
        script_excerpt = script_excerpt[:3500] + "..."

    if match_script_order:
        ordering = (
            "Order terms in the same narrative order as the script "
            "(first term for opening scene, last for ending)."
        )
        example = '["medieval court", "pig farm", "village trial", "gallows"]'
    else:
        ordering = "Order by visual relevance."
        example = '["medieval history", "old manuscript", "castle"]'

    prompt = f"""Generate exactly {amount} short English video search keywords for stock footage (Pexels).
{ordering}
Return ONLY a JSON array of strings, no markdown, no explanation.
Example: {example}

Video subject: {subject}

Script:
{script_excerpt}
"""

    client = _client()
    resp = client.chat.completions.create(
        model=model,
        messages=[{"role": "user", "content": prompt}],
        temperature=0.4,
        max_tokens=512,
    )
    raw = (resp.choices[0].message.content or "").strip()
    terms = _parse_terms_json(raw)
    if not terms:
        raise RuntimeError("LLM не вернул ключевые слова для видео (video_terms)")
    return terms[:amount]


def _parse_terms_json(raw: str) -> list[str]:
    raw = re.sub(r"^```(?:json)?\s*", "", raw.strip())
    raw = re.sub(r"\s*```$", "", raw)
    try:
        data = json.loads(raw)
    except json.JSONDecodeError:
        match = re.search(r"\[.*\]", raw, re.DOTALL)
        if not match:
            return []
        data = json.loads(match.group())
    if not isinstance(data, list):
        return []
    out: list[str] = []
    for item in data:
        if isinstance(item, str):
            cleaned = item.strip()
            if cleaned:
                out.append(cleaned)
    return out

