def _trim_to_max_words(paragraphs: list[str], max_words: int) -> list[str]:
    """Обрезает сценарий, если LLM превысил лимит — для стабильной озвучки edge_tts."""
    words_used = 0
    trimmed: list[str] = []
    for para in paragraphs:
        para_words = re.findall(r"\w+", para, flags=re.UNICODE)
        if words_used + len(para_words) <= max_words:
            trimmed.append(para)
            words_used += len(para_words)
            continue
        remaining = max_words - words_used
        if remaining <= 0:
            break
        kept = para_words[:remaining]
        if kept:
            trimmed.append(" ".join(kept))
        break
    return trimmed if trimmed else paragraphs[:1]


