    from pydub import AudioSegment

    _configure_pydub_ffmpeg(AudioSegment)
    ensure_file_path_exists(voice_file)
    temp_dir = os.path.dirname(voice_file) or utils.storage_dir("temp")
    combined = AudioSegment.empty()
    logger.info(f"azure_tts_v1: split into {len(chunks)} chunks for long script")

    for index, chunk in enumerate(chunks):
        chunk_file = os.path.join(temp_dir, f"tts_chunk_{index}.mp3")
        sub_maker = _azure_tts_v1_single(chunk, voice_name, voice_rate, chunk_file)
        if sub_maker is None:
            logger.error(f"azure_tts_v1: chunk {index + 1}/{len(chunks)} failed")
            return None
        combined += AudioSegment.from_file(chunk_file, format="mp3")
        if index + 1 < len(chunks):
            time.sleep(0.3)

    combined.export(voice_file, format="mp3")
    duration_seconds = len(combined) / 1000.0
    logger.info(
        f"azure_tts_v1: merged {len(chunks)} chunks, duration={duration_seconds:.1f}s"
    )
    return populate_legacy_submaker_with_full_text(
        ensure_legacy_submaker_fields(SubMaker()),
        text,
        duration_seconds,
    )


